import { useMemo } from 'react';
import {
  LineChart, Line, BarChart, Bar, XAxis, YAxis, CartesianGrid,
  Tooltip, Legend, ResponsiveContainer
} from 'recharts';
import { filterData, formatKRW, formatShort } from '../utils/calcMetrics';
import './CumulativeTrend.css';

export default function CumulativeTrend({ allData, filters }) {
  // 누적 매출 (연도별)
  const cumulativeByYear = useMemo(() => {
    const filtered = filterData(allData, filters);
    const yearMap = {};

    filtered.forEach((d) => {
      if (!yearMap[d.year]) yearMap[d.year] = {};
      if (!yearMap[d.year][d.month]) yearMap[d.year][d.month] = 0;
      yearMap[d.year][d.month] += d.totalSales || 0;
    });

    const months = Array.from({ length: 12 }, (_, i) => i + 1);
    const result = months.map((m) => {
      const entry = { month: m };
      Object.entries(yearMap).forEach(([year, monthData]) => {
        let cumulative = 0;
        for (let i = 1; i <= m; i++) {
          cumulative += monthData[i] || 0;
        }
        entry[year] = cumulative;
      });
      return entry;
    });

    return result;
  }, [allData, filters]);

  // 월별 추이 (3개월 이동평균)
  const monthlyTrendWithMA = useMemo(() => {
    const filtered = filterData(allData, filters);
    const monthMap = {};

    filtered.forEach((d) => {
      const key = `${d.year}-${String(d.month).padStart(2, '0')}`;
      if (!monthMap[key]) {
        monthMap[key] = { yearMonth: key, sales: 0 };
      }
      monthMap[key].sales += d.totalSales || 0;
    });

    const data = Object.values(monthMap)
      .sort((a, b) => a.yearMonth.localeCompare(b.yearMonth))
      .map((m, idx, arr) => {
        let ma3 = m.sales;
        if (idx >= 1 && idx < arr.length) {
          ma3 = (arr[idx - 1].sales + m.sales + (arr[idx + 1]?.sales || m.sales)) / 3;
        }
        return { ...m, ma3 };
      });

    return data;
  }, [allData, filters]);

  // 순매출 vs 총 매출 비교
  const netVsGross = useMemo(() => {
    const filtered = filterData(allData, filters);
    const monthMap = {};

    filtered.forEach((d) => {
      const key = `${d.year}-${String(d.month).padStart(2, '0')}`;
      if (!monthMap[key]) {
        monthMap[key] = { yearMonth: key, gross: 0, net: 0 };
      }
      monthMap[key].gross += d.totalSales || 0;
      d.products.forEach((prod) => {
        monthMap[key].net += prod.netSales || 0;
      });
    });

    return Object.values(monthMap)
      .sort((a, b) => a.yearMonth.localeCompare(b.yearMonth));
  }, [allData, filters]);

  if (allData.length === 0) {
    return <div className="daily-empty">파일을 먼저 업로드해주세요.</div>;
  }

  const years = Object.keys(
    cumulativeByYear.reduce((acc, m) => {
      Object.keys(m).forEach((k) => {
        if (k !== 'month') acc[k] = true;
      });
      return acc;
    }, {})
  ).sort();

  return (
    <div className="cumulative-trend">
      {/* 연도별 누적 매출 */}
      {cumulativeByYear.length > 0 && (
        <div className="chart-card">
          <div className="chart-title">연도별 누적 매출 (1월→12월)</div>
          <ResponsiveContainer width="100%" height={300}>
            <LineChart data={cumulativeByYear} margin={{ top: 10, right: 20, left: 20, bottom: 5 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
              <XAxis
                dataKey="month"
                label={{ value: '월', position: 'insideRight', offset: -5 }}
                tick={{ fontSize: 11 }}
              />
              <YAxis tickFormatter={formatShort} tick={{ fontSize: 11 }} />
              <Tooltip formatter={(v) => [`${formatKRW(v)}원`, '']} />
              <Legend />
              {years.map((year, idx) => {
                const colors = ['#0d2258', '#1d4ed8', '#7c3aed', '#0f766e', '#dc2626', '#d97706', '#059669'];
                return (
                  <Line
                    key={year}
                    type="monotone"
                    dataKey={year}
                    stroke={colors[idx % colors.length]}
                    strokeWidth={2}
                    dot={{ r: 3 }}
                    name={`${year}년`}
                  />
                );
              })}
            </LineChart>
          </ResponsiveContainer>
        </div>
      )}

      {/* 월별 추이 + 3개월 이동평균 */}
      {monthlyTrendWithMA.length > 0 && (
        <div className="chart-card">
          <div className="chart-title">월별 추이 (3개월 이동평균)</div>
          <ResponsiveContainer width="100%" height={300}>
            <LineChart data={monthlyTrendWithMA} margin={{ top: 10, right: 20, left: 20, bottom: 5 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
              <XAxis dataKey="yearMonth" tick={{ fontSize: 11 }} />
              <YAxis tickFormatter={formatShort} tick={{ fontSize: 11 }} />
              <Tooltip formatter={(v) => [`${formatKRW(v)}원`, '']} />
              <Legend />
              <Line
                type="monotone"
                dataKey="sales"
                stroke="#d1d5db"
                strokeWidth={1}
                dot={false}
                name="월별 매출"
              />
              <Line
                type="monotone"
                dataKey="ma3"
                stroke="#0d2258"
                strokeWidth={2.5}
                dot={{ r: 3 }}
                name="3개월 이동평균"
              />
            </LineChart>
          </ResponsiveContainer>
        </div>
      )}

      {/* 순 매출 vs 총 매출 비교 */}
      {netVsGross.length > 0 && (
        <div className="chart-card">
          <div className="chart-title">순매출 vs 총매출 비교</div>
          <ResponsiveContainer width="100%" height={300}>
            <BarChart data={netVsGross} margin={{ top: 10, right: 20, left: 20, bottom: 5 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
              <XAxis dataKey="yearMonth" tick={{ fontSize: 11 }} />
              <YAxis tickFormatter={formatShort} tick={{ fontSize: 11 }} />
              <Tooltip formatter={(v) => [`${formatKRW(v)}원`, '']} />
              <Legend />
              <Bar dataKey="gross" fill="#1d4ed8" name="총매출" />
              <Bar dataKey="net" fill="#0d2258" name="순매출" />
            </BarChart>
          </ResponsiveContainer>
        </div>
      )}

      {/* 통계 */}
      <div className="trend-stats">
        <div className="stat-card">
          <div className="stat-label">최근 월 매출</div>
          <div className="stat-value">
            {monthlyTrendWithMA.length > 0
              ? formatKRW(monthlyTrendWithMA[monthlyTrendWithMA.length - 1].sales)
              : '-'}
            원
          </div>
        </div>
        <div className="stat-card">
          <div className="stat-label">평균 월 매출</div>
          <div className="stat-value">
            {monthlyTrendWithMA.length > 0
              ? formatKRW(
                  Math.round(
                    monthlyTrendWithMA.reduce((s, m) => s + m.sales, 0) / monthlyTrendWithMA.length
                  )
                )
              : '-'}
            원
          </div>
        </div>
        <div className="stat-card">
          <div className="stat-label">최고 월 매출</div>
          <div className="stat-value">
            {monthlyTrendWithMA.length > 0
              ? formatKRW(Math.max(...monthlyTrendWithMA.map((m) => m.sales)))
              : '-'}
            원
          </div>
        </div>
        <div className="stat-card">
          <div className="stat-label">최저 월 매출</div>
          <div className="stat-value">
            {monthlyTrendWithMA.length > 0
              ? formatKRW(Math.min(...monthlyTrendWithMA.map((m) => m.sales)))
              : '-'}
            원
          </div>
        </div>
      </div>
    </div>
  );
}
